const __pageData = JSON.parse('{"title":"10. Large AI Model Courses","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10_Large_AI_Model_Courses.md","filePath":"docs/10_Large_AI_Model_Courses.md"}');
